// Sidebar behavior: highlight the active nav link and drive the "+ New page"
// dialog (title + custom Location picker + live path preview). The markup this
// script targets is generated by wiki-build-preamble in publish.el.
(function () {
  var path = window.location.pathname;
  document.querySelectorAll('nav a').forEach(function (a) {
    var dir = a.getAttribute('href').replace('index.html', '');
    var match = (dir === '/') ? (path === '/' || path === '/index.html')
                              : path.startsWith(dir);
    if (match) a.classList.add('active');
  });

  // ── Collapsible nav sections ──
  // Each section's open/closed state is keyed by the parent link's href and
  // persisted in localStorage so it survives navigation between pages.
  var COLLAPSE_KEY = 'navCollapsed';
  var collapsedState = {};
  try { collapsedState = JSON.parse(localStorage.getItem(COLLAPSE_KEY)) || {}; }
  catch (e) { collapsedState = {}; }

  function liKey(li) {
    var link = li.querySelector(':scope > .nav-row > a');
    return link ? link.getAttribute('href') : null;
  }
  function setCollapsed(li, isCollapsed) {
    li.classList.toggle('collapsed', isCollapsed);
    var toggle = li.querySelector(':scope > .nav-row > .nav-toggle');
    if (toggle) toggle.setAttribute('aria-expanded', String(!isCollapsed));
  }

  document.querySelectorAll('nav .nav-toggle').forEach(function (toggle) {
    var li = toggle.closest('li');
    var key = liKey(li);
    if (key && collapsedState[key]) setCollapsed(li, true);
    toggle.addEventListener('click', function (e) {
      e.preventDefault();
      var nowCollapsed = !li.classList.contains('collapsed');
      setCollapsed(li, nowCollapsed);
      if (key) {
        collapsedState[key] = nowCollapsed;
        try { localStorage.setItem(COLLAPSE_KEY, JSON.stringify(collapsedState)); }
        catch (e2) {}
      }
    });
  });

  // Always keep the current page reachable: expand every ancestor section.
  document.querySelectorAll('nav a.active').forEach(function (a) {
    var node = a.closest('li');
    while (node) {
      setCollapsed(node, false);
      var parent = node.parentElement;
      node = parent ? parent.closest('li') : null;
    }
  });

  // ── Nav label tooltips ──
  // Nav links are truncated with an ellipsis when a label is wider than the
  // sidebar. On hover, show the full label in a floating box, but only when
  // it's actually truncated (scrollWidth > clientWidth).
  var navTooltip = document.createElement('div');
  navTooltip.className = 'nav-tooltip';
  navTooltip.setAttribute('hidden', '');
  document.body.appendChild(navTooltip);

  document.querySelectorAll('nav .nav-tree a').forEach(function (a) {
    a.addEventListener('mouseenter', function () {
      if (a.scrollWidth <= a.clientWidth) return;
      var rect = a.getBoundingClientRect();
      navTooltip.textContent = a.textContent;
      navTooltip.removeAttribute('hidden');
      navTooltip.style.left = rect.right + 6 + 'px';
      navTooltip.style.top = rect.top + 'px';
    });
    a.addEventListener('mouseleave', function () {
      navTooltip.setAttribute('hidden', '');
    });
  });

  var overlay = document.getElementById('np-overlay');
  var titleEl = document.getElementById('np-title');
  var previewEl = document.getElementById('np-preview');
  var errorEl = document.getElementById('np-error');
  var createEl = document.getElementById('np-create');

  // Custom Location picker (a native <select> can't show a styled hierarchy).
  var pickerBtn = document.getElementById('np-picker-btn');
  var pickerList = document.getElementById('np-picker-list');
  var pickerLabel = document.getElementById('np-picker-selected');
  var opts = Array.prototype.slice.call(pickerList.querySelectorAll('.np-opt'));
  var selected = opts[0]; // defaults to the Top level row

  // Mirror serve.py's slugify so the preview matches the real path.
  function slugify(s) {
    return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  }
  function currentPath() {
    var dir = selected ? (selected.getAttribute('data-dir') || '') : '';
    var slug = slugify(titleEl.value) || '…';
    return '/' + (dir ? dir + '/' : '') + slug + '/index.html';
  }
  function refresh() { previewEl.textContent = currentPath(); }

  function setSelected(opt) {
    selected = opt;
    opts.forEach(function (o) { o.setAttribute('aria-selected', o === opt ? 'true' : 'false'); });
    pickerLabel.textContent = opt.textContent;
    refresh();
  }

  // Default the Location to the page the user is currently on, so a new page
  // nests under it. Prefer an exact match on the current URL; otherwise fall
  // back to the deepest section that is an ancestor of the current path.
  function defaultOpt() {
    var here = window.location.pathname;
    for (var i = 0; i < opts.length; i++) {
      if (opts[i].getAttribute('data-value') === here) return opts[i];
    }
    var dir = here.replace(/[^/]*$/, '').replace(/^\/|\/$/g, ''); // current directory
    var best = opts[0], bestLen = -1;
    for (var j = 0; j < opts.length; j++) {
      var d = opts[j].getAttribute('data-dir') || '';
      if (d && (dir === d || dir.indexOf(d + '/') === 0) && d.length > bestLen) {
        best = opts[j]; bestLen = d.length;
      }
    }
    return best;
  }

  function openList() {
    pickerList.hidden = false;
    pickerBtn.setAttribute('aria-expanded', 'true');
    if (selected) selected.scrollIntoView({ block: 'nearest' });
  }
  function closeList() {
    pickerList.hidden = true;
    pickerBtn.setAttribute('aria-expanded', 'false');
  }
  function listOpen() { return !pickerList.hidden; }

  pickerBtn.addEventListener('click', function () { listOpen() ? closeList() : openList(); });
  pickerList.addEventListener('click', function (e) {
    var opt = e.target.closest('.np-opt');
    if (!opt) return;
    setSelected(opt);
    closeList();
    pickerBtn.focus();
  });
  pickerBtn.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!listOpen()) { openList(); return; }
      var i = opts.indexOf(selected);
      i = e.key === 'ArrowDown' ? Math.min(opts.length - 1, i + 1) : Math.max(0, i - 1);
      setSelected(opts[i]);
      opts[i].scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault(); listOpen() ? closeList() : openList();
    }
  });

  function open() {
    overlay.hidden = false;
    errorEl.hidden = true;
    closeList();
    setSelected(defaultOpt());
    titleEl.focus();
  }
  function close() {
    overlay.hidden = true;
    closeList();
    titleEl.value = '';
    setSelected(opts[0]);
    createEl.disabled = false;
    createEl.textContent = 'Create page';
  }

  document.getElementById('np-open').addEventListener('click', open);
  document.getElementById('np-cancel').addEventListener('click', close);
  overlay.addEventListener('click', function (e) { if (e.target === overlay) close(); });
  document.addEventListener('click', function (e) {
    if (listOpen() && !e.target.closest('#np-picker')) closeList();
  });
  document.addEventListener('keydown', function (e) {
    if (overlay.hidden || e.key !== 'Escape') return;
    if (listOpen()) { closeList(); pickerBtn.focus(); } else { close(); }
  });
  titleEl.addEventListener('input', refresh);
  titleEl.addEventListener('keydown', function (e) { if (e.key === 'Enter') submit(); });

  function submit() {
    var label = titleEl.value.trim();
    if (!label) { titleEl.focus(); return; }
    errorEl.hidden = true;
    createEl.disabled = true;
    createEl.textContent = 'Building…';
    fetch('/api/new-tab', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ label: label, parentHref: selected.getAttribute('data-value') || null })
    }).then(function (r) { return r.json(); }).then(function (res) {
      if (res.ok) { window.location.href = res.href; return; }
      errorEl.textContent = res.error;
      errorEl.hidden = false;
      createEl.disabled = false;
      createEl.textContent = 'Create page';
    }).catch(function () {
      errorEl.textContent = 'Could not reach the build server. Is serve.py running?';
      errorEl.hidden = false;
      createEl.disabled = false;
      createEl.textContent = 'Create page';
    });
  }
  createEl.addEventListener('click', submit);
}());
